LogicDefinition.ScriptText:
#load "reference"
using FS.SDK.Components;

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Schublade_Helper                                                                     //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    18.06.2025       1.4             DW              Durchschleifen von Limits
//    18.06.2025       1.2             DW              Header integriert, Logik erstellt
//    05.12.2025       1.5.0           Egg             Code optimiert
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              x              DW            Verhaltensmodell für Fio geprüft
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik dient als Rubberbandingfunktion für Schubladen, Schieber oder ähnliche Komponenten die per Roboter
//    oder andersweitig gezogen oder geschoben werden
//
//============================================================================================================
//
//    Input Slot Values
//    Trigger_Sensor                    =   Bool, Sensor zur Überwachung (Pin an Position)
//    Release_Clamping                  =   Bool, Sensor zur Drucküberwachung
//    Actual_Position                   =   Real, Überwachung der aktuellen Position
//    Limit_Min_Value                   =   Real, Setzen des unteren Limits der Achse
//    Limit_Max_Value                   =   Real, Setzen des oberen Limits der Achse
//
//    Output Slot Values
//    SIM_TargetPosition                =   Real, Errechneter Übergabewert für Motionjoint
//    Limit_Min_Position                =   Real, Übergabewert des unteren Limits
//    Limit_Max_Position                =   Real, Übergabewert des oberen Limits
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////


//============================================================================================================
// Auslesen der Initial Positionen
//============================================================================================================





var parent = SceneObject.Parent;
if(parent == null) return;

var collider = parent.GetComponent<ColliderComponent>();
if(collider == null) return;

var collisionList = collider.CollisionList;

//Limit_Min_Position = Limit_Min_Value;
//Limit_Max_Position = Limit_Max_Value;

if(Trigger_Sensor && collisionList.Any() && Release_Clamping)
{

    if(!_positionSaved)
    {
        _basePosition_X = collisionList.FirstOrDefault().Transform.Position.X;
        _basePosition_Y = collisionList.FirstOrDefault().Transform.Position.Y;
        _basePosition_Z = collisionList.FirstOrDefault().Transform.Position.Z;
        _positionSaved = true;
        Actual_PositionSaved = Actual_Position;
    }

    SIM_TargetPosition =  collisionList.FirstOrDefault().Transform.Position.X  - _basePosition_X + Actual_PositionSaved;
    SIM_Velocity = 100000f;




}
else
{
    _positionSaved = false;
    Release_Clamping = false;
}
